// Mes yeux — fichier unique. Lance avec : node start.mjs   (Node >= 22.13)
// Variables : APP_PASSWORD (obligatoire), PORT, DATA_DIR. Les clés (Apify, Gemini/Groq, bot Telegram) se collent dans Réglages.
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { pathToFileURL } from 'node:url';

if (!process.env.APP_PASSWORD) {
  console.error("❌ Définis la variable APP_PASSWORD (le mot de passe de ton appli) puis relance.");
  process.exit(1);
}
const BUNDLE = '';

const dir = path.resolve('.mesyeux-app');
const files = JSON.parse(zlib.gunzipSync(Buffer.from(BUNDLE, 'base64')).toString('utf8'));
for (const [p, content] of Object.entries(files)) {
  const f = path.join(dir, p);
  fs.mkdirSync(path.dirname(f), { recursive: true });
  fs.writeFileSync(f, content);
}
process.env.HOST ??= '0.0.0.0';
await import(pathToFileURL(path.join(dir, 'server.js')).href);
